<?php $labels=['draft'=>'Rascunho','sent'=>'Enviado','viewed'=>'Visualizado','signed'=>'Assinado','cancelled'=>'Cancelado']; ?>
<div class="page-header"><div><p class="eyebrow">Franquias</p><h1>Contratos</h1><p>Geração, envio, assinatura e situação financeira dos contratos da rede.</p></div><a class="button button-secondary" href="<?= $escape($basePath) ?>/admin/franchise-contract-templates"><i class="fa-solid fa-file-pen"></i> Modelos</a></div>
<?php if(!empty($message)):?><div class="alert alert-success"><?= $escape($message) ?></div><?php endif;?><?php if(!empty($error)):?><div class="alert alert-danger"><?= $escape($error) ?></div><?php endif;?>
<div class="table-card"><table><thead><tr><th>Contrato</th><th>Franquia</th><th>Situação</th><th>Assinatura</th><th>Cobrança</th><th>Atualizado</th><th>Ação</th></tr></thead><tbody><?php foreach($contracts as$item):?><tr><td><strong><?= $escape($item['title']) ?></strong><small>#<?= (int)$item['id'] ?></small></td><td><?= $escape($item['franchise_name']) ?><small><?= $escape($item['cnpj']) ?></small></td><td><span class="status"><?= $escape($labels[$item['status']]??$item['status']) ?></span></td><td><?= $item['signed_at']?$escape(date('d/m/Y H:i',strtotime((string)$item['signed_at']))):'Pendente' ?></td><td><?php if((int)$item['billing_required']!==1):?>Não prevista<?php elseif(!empty($item['asaas_payment_id'])):?><span class="status"><?= $escape(['PENDING'=>'Pendente','CONFIRMED'=>'Confirmada','RECEIVED'=>'Recebida','OVERDUE'=>'Vencida'][$item['asaas_payment_status']]??$item['asaas_payment_status']??'Emitida') ?></span><?php elseif($item['status']==='signed'):?>Pronta para emitir<?php else:?>Aguarda assinatura<?php endif;?></td><td><?= $escape(date('d/m/Y H:i',strtotime((string)$item['updated_at']))) ?></td><td><a class="button button-secondary button-small" href="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$item['id'] ?>"><i class="fa-solid fa-eye"></i> Abrir</a></td></tr><?php endforeach;?><?php if($contracts===[]):?><tr><td colspan="7">Nenhum contrato gerado.</td></tr><?php endif;?></tbody></table></div>
